/* Contractual billing controls, inserted inside the application controller. */
 const B=globalThis.RodavoltRental;
 const rentalWeekdays=[['0','Domingo'],['1','Segunda-feira'],['2','Terça-feira'],['3','Quarta-feira'],['4','Quinta-feira'],['5','Sexta-feira'],['6','Sábado']];
 function rentalPanel(){const schedules=B.schedules(ops),contracts=K.contracts(ops).filter(c=>c.modelId==='rental'&&c.status==='signed'),pending=contracts.filter(c=>!schedules.some(s=>s.contractId===c.id&&s.contractVersion===c.version&&s.status!=='ended'));return panel('Aluguéis por contrato',`<p class="caption">A semana utilizada vence no dia combinado. O valor vem da versão assinada. Emitir cobrança cria um compromisso; dinheiro entra somente quando o recebimento é conferido.</p>${schedules.length?table(['Motorista e contrato','Regras preservadas','Cobertura','Ações'],schedules.map(s=>`<tr><td><strong>${esc(M.driver(ops,s.driverId).name)}</strong><small>${esc(s.contractId)} v${s.contractVersion} · ${esc(s.vehicleId)} · ciclo ${s.cycle+1}</small></td><td>${cash(s.weeklyAmount)} por semana<small>${s.paymentTiming==='arrears'?'Pela semana utilizada':'Antecipado'} · ${rentalWeekdays.find(([k])=>Number(k)===s.dueWeekday)?.[1]}</small><small>Primeira: ${s.firstWeek==='proportional'?'proporcional':'inteira'} · Última: ${s.lastWeek==='proportional'?'proporcional':'inteira'}</small></td><td>Desde ${date(s.startDate)}<small>${tag(s.status==='active'?'Em andamento':s.status==='ended'?'Encerrada':M.driver(ops,s.driverId).stage==='active'?'Pronta para ativar':'Aguardando entrega',s.status==='active'?'green':'')}</small>${s.openingCoverageThrough?`<small>Abertura preservada até ${date(s.openingCoverageThrough)}</small>`:''}</td><td>${btn('Ver agenda','rental-history','',`data-id="${s.id}"`)}${s.status==='configured'&&M.driver(ops,s.driverId).stage==='active'?btn('Ativar agenda','rental-activate','',`data-driver="${s.driverId}"`):''}</td></tr>`).join('')):'<div class="notice">As quatro cobranças iniciais são exemplos preservados. Nenhuma regra de vencimento ou proporcionalidade foi aplicada a elas automaticamente.</div>'}<div class="actions gap">${pending.map(c=>btn('Configurar · '+esc(M.driver(ops,c.driverId).name),'rental-configure','',`data-id="${c.id}"`)).join('')}${schedules.some(s=>s.status==='active')?btn('Emitir semanas vencidas','rental-generate','primary'):''}</div>${!pending.length&&!schedules.length?'<p class="caption">Conclua um contrato em Meu advogado para configurar suas cobranças.</p>':''}`);}
 function rentalConfigureForm(c){const old=ops.charges.filter(q=>q.driverId===c.driverId&&!q.rentalScheduleId),latest=old.map(q=>q.date).sort().at(-1),start=latest||K.operatingDate;return `<form id="rental-configure-form"><input type="hidden" name="contractId" value="${esc(c.id)}"><input type="hidden" name="driverId" value="${esc(c.driverId)}"><div class="notice">${esc(M.driver(ops,c.driverId).name)} · ${esc(c.vehicleId)}<br>${esc(c.id)} v${c.version} · <strong>${cash(c.weekly)} por semana</strong><br>O contrato assinado permanece preservado. Confira as condições antes de ativar a agenda.</div><div class="fields gap">${input('startDate','Data efetiva da entrega / início da nova agenda',start,'type="date" required')}${select('paymentTiming','Quando a semana é paga?','arrears',[['arrears','Depois de utilizar a semana'],['advance','Antes de utilizar a semana']],'required')}${select('dueWeekday','Dia combinado para o vencimento','',[['','Escolha o dia'],...rentalWeekdays],'required')}${select('firstWeek','Primeira semana incompleta','',[['','Escolha a regra'],['proportional','Somente os dias utilizados'],['full','Valor da semana inteira']],'required')}${select('lastWeek','Última semana incompleta','',[['','Escolha a regra'],['proportional','Somente os dias utilizados'],['full','Valor da semana inteira']],'required')}${old.length?input('openingCoverageThrough','Último dia já coberto pelas cobranças de abertura','','type="date" required'):''}${input('confirmedConditions','Conferência das condições e referência do acordo','','required maxlength="1000" placeholder="Ex.: condições conferidas com o contrato demonstrativo"')}</div><p class="caption gap">O dia escolhido inicia cada semana completa. Na cobrança posterior, ela vence no mesmo dia da semana seguinte. Os dias da entrega e da devolução contam. Proporcional = valor semanal × dias ÷ 7, arredondado em centavos. Se a primeira semana também for a última, prevalece a regra da última. Não há multa, juros ou reajuste automáticos.</p>${old.length?`<p class="caption">Há ${old.length} cobranças históricas preservadas. Informe a cobertura conferida; a nova agenda começa no dia seguinte e sua primeira cobrança vence depois das anteriores.</p>`:''}<div class="form-actions"><button class="btn primary" type="submit">Conferir agenda antes de salvar</button></div></form>`;}
 function rentalHistory(s){const list=ops.charges.filter(q=>q.rentalScheduleId===s.id),preview=B.periodList(s).slice(0,8);return `<p class="caption">${esc(s.contractId)} v${s.contractVersion} · ${cash(s.weeklyAmount)} por semana · valores contratados preservados.</p>${table(['Período utilizado','Vencimento','Valor','Situação'],list.map(q=>`<tr><td>${date(q.periodStart)} a ${date(q.finalPeriodEnd||q.periodEnd)}<small>${esc(q.id)}</small></td><td>${date(q.date)}</td><td>${cash(q.adjustedAmount??q.amount)}${q.adjustedAmount!==undefined&&q.adjustedAmount!==q.amount?`<small>Original ${cash(q.amount)} · ajuste preservado</small>`:''}</td><td>${tag(q.status==='paid'?'Conferida':'Em aberto',q.status==='paid'?'green':'amber')}</td></tr>`).join('')||'<tr><td colspan="4">Aguardando o primeiro vencimento da agenda.</td></tr>')}<details class="gap"><summary>Próximas semanas · previsão sem emissão</summary>${table(['Uso','Vence','Valor'],preview.map(p=>`<tr><td>${date(p.start)} a ${date(p.end)} · ${p.days} dia(s)</td><td>${date(p.due)}</td><td>${cash(p.amount)}</td></tr>`).join(''))}</details>`;}
 function rentalAction(action,e){if(!action.startsWith('rental-'))return false;if(mode!=='admin')throw new RangeError('A gestão configura a agenda de aluguel.');if(action==='rental-driver-configure'){const c=K.contracts(ops,e.dataset.driver).filter(c=>c.modelId==='rental'&&c.status==='signed').at(-1);if(!c)throw new RangeError('Conclua o contrato em Meu advogado antes de configurar cobranças.');open('Combinar a cobrança semanal',rentalConfigureForm(c));}else if(action==='rental-configure'){const c=K.contracts(ops).find(c=>c.id===e.dataset.id);if(!c)throw new RangeError('Contrato não encontrado.');open('Combinar a cobrança semanal',rentalConfigureForm(c));}else if(action==='rental-history'){const s=B.schedules(ops).find(s=>s.id===e.dataset.id);if(!s)throw new RangeError('Agenda não encontrada.');open('Agenda do aluguel',rentalHistory(s));}else if(action==='rental-activate'){B.activate(ops,e.dataset.driver,K.operatingDate);render();persist();toast('Agenda ativada. Cobranças aparecem conforme o vencimento.');}else if(action==='rental-generate'){open('Emitir semanas vencidas',`<form id="rental-generate-form">${input('through','Emitir vencimentos até',K.operatingDate,'type="date" required')}<p class="caption gap">As cobranças são as mesmas na gestão e no app. Repetir a emissão não duplica a semana e não recebe dinheiro.</p><div class="form-actions"><button class="btn primary" type="submit">Emitir cobranças</button></div></form>`);}else return false;return true;}
 function rentalSubmit(form,f){if(!form.id.startsWith('rental-'))return false;if(mode!=='admin')throw new RangeError('A gestão configura a agenda de aluguel.');if(form.id==='rental-configure-form'){const values=Object.fromEntries(f.entries()),candidate=JSON.parse(JSON.stringify(ops)),schedule=B.configure(candidate,values),first=B.periodList(schedule)[0];open('Confira a primeira cobrança',`<form id="rental-save-form">${Object.entries(values).map(([k,v])=>`<input type="hidden" name="${esc(k)}" value="${esc(v)}">`).join('')}${row('Contrato',esc(schedule.contractId)+' v'+schedule.contractVersion)}${row('Primeiro período',date(first.start)+' a '+date(first.end),first.days+' dia(s) utilizados')}${row('Primeiro vencimento',date(first.due))}${row('Primeiro valor',cash(first.amount))}<label class="check gap"><input type="checkbox" name="confirmed" required>Conferi a agenda e as condições do contrato demonstrativo.</label><div class="form-actions"><button type="submit" class="btn primary">Salvar agenda de cobrança</button></div></form>`);return true;}if(form.id==='rental-save-form'){if(!f.has('confirmed'))throw new RangeError('Confira a agenda antes de salvar.');B.configure(ops,Object.fromEntries(f.entries()));close();render();persist();toast('Agenda preservada. Será ativada na entrega ou pela gestão para um vínculo já ativo.');return true;}if(form.id==='rental-generate-form'){const created=B.generateThrough(ops,String(f.get('through')));close();render();persist();toast(created.length+' cobrança(s) nova(s). Nenhum recebimento foi registrado.');return true;}return false;}
